#include <iostream>
#include <unordered_map>
#include <list>
#include <utility>
#include <stdexcept>

class LRUCache {
private:
    int capacity_;
    // 双向链表：头部存最近访问(MRU)，尾部存最久未访问(LRU)
    std::list<std::pair<int, int>> cache_list_;
    // 哈希表：key -> 链表节点迭代器
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> cache_map_;

public:
    explicit LRUCache(int capacity) : capacity_(capacity) {
        if (capacity_ <= 0) {
            throw std::invalid_argument("LRU Cache capacity must be > 0");
        }
    }

    int get(int key) {
        auto it = cache_map_.find(key);
        if (it == cache_map_.end()) {
            return -1; // Key 不存在
        }

        // ⭐ 关键：将已访问节点直接移动到链表头部（O(1)）
        cache_list_.splice(cache_list_.begin(), cache_list_, it->second);

        // it->second 仍指向原节点对象（地址未变），只是位置变了
        return it->second->second;
    }

    void put(int key, int value) {
        auto it = cache_map_.find(key);
        if (it != cache_map_.end()) {
            // 键已存在：更新值并提升为最新访问
            it->second->second = value;
            cache_list_.splice(cache_list_.begin(), cache_list_, it->second);
            return;
        }

        // 键不存在：检查是否需要淘汰 LRU
        if (cache_list_.size() == static_cast<size_t>(capacity_)) {
            int lru_key = cache_list_.back().first;
            cache_map_.erase(lru_key);      // O(1) 删除映射
            cache_list_.pop_back();         // O(1) 弹出尾部节点
        }

        // 插入新节点到头部
        cache_list_.push_front({key, value});
        cache_map_[key] = cache_list_.begin();
    }
};

